-- Conteúdo público aprovado. Nunca substitui um catálogo já preenchido.
insert into public.studio_content(id,data,revision) values(1,'{"slogan":"Um toque de magia em cada lembrança.","intro":"Transformamos suas fotografias em cenários cheios de delicadeza e imaginação. Ensaios virtuais e criações digitais para celebrar momentos especiais.","about":"O Encanto no Retrato Studio IA é um estúdio de criação digital dedicado a transformar fotografias em lembranças criativas. Unimos sensibilidade estética e inteligência artificial para construir cenários e composições personalizados, sem a necessidade de um ensaio presencial.","mission":"Celebrar histórias e fases especiais com imagens acessíveis, delicadas e cuidadosas, respeitando a privacidade e a autorização de cada família.","heroImage":"/images/studio-balloons.svg","facebook":"","instagram":"https://www.instagram.com/encantonoretrato.studioia/","messenger":"","instagramDirect":"https://ig.me/m/encantonoretrato.studioia","categories":["Recém-nascidos","Ensaios infantis","Mesversários","Aniversários","Datas comemorativas","Gestantes e família","Convites personalizados","Transformações com IA"],"photos":[{"id":"rn-01","title":"Doce Soninho","album":"Recém-nascidos","image":"/images/recem-nascidos/RN_01_Doce_Soninho.jpg","description":"Um ensaio clássico e aconchegante em tons de bege, com tricô delicado, cestinha de vime e ursinho de pelúcia.","kind":"ai","sample":false,"customization":""},{"id":"rn-02","title":"Pequeno Anjo","album":"Recém-nascidos","image":"/images/recem-nascidos/RN_02_Pequeno_Anjo.jpg","description":"Um cenário celestial delicado, com nuvens fofinhas, lua dourada e pequenas estrelas luminosas.","kind":"ai","sample":true,"customization":""},{"id":"rn-03","title":"Jardim dos Sonhos","album":"Recém-nascidos","image":"/images/recem-nascidos/RN_03_Jardim_dos_Sonhos.jpg","description":"Um jardim encantado de rosas delicadas, tons rosados e luzes quentes, com atmosfera romântica.","kind":"ai","sample":true,"customization":""},{"id":"inf-01","title":"Doce Encanto","album":"Ensaios infantis","image":"/images/ensaios-infantis/INF_01_Doce_Encanto.jpg","description":"Um retrato clássico e delicado, com vestido rendado, tons creme e iluminação suave de estúdio.","kind":"ai","sample":true,"customization":""},{"id":"inf-02","title":"Jardim das Fadas","album":"Ensaios infantis","image":"/images/ensaios-infantis/INF_02_Jardim_das_Fadas.jpg","description":"Um jardim encantado de flores rosadas, asas luminosas e borboletas douradas.","kind":"ai","sample":true,"customization":""},{"id":"inf-03","title":"Pequeno Aviador","album":"Ensaios infantis","image":"/images/ensaios-infantis/INF_03_Pequeno_Aviador.jpg","description":"Uma aventura vintage com roupa de aviador, avião de madeira e cenário de viagem.","kind":"ai","sample":true,"customization":""},{"id":"inf-04","title":"Reino dos Sonhos","album":"Ensaios infantis","image":"/images/ensaios-infantis/INF_04_Reino_dos_Sonhos.jpg","description":"Um pequeno príncipe diante de um castelo de conto de fadas ao pôr do sol.","kind":"ai","sample":true,"customization":""},{"id":"mes-01","title":"Ursinho dos Sonhos","album":"Mesversários","image":"/images/mesversarios/MES_01_Ursinho_dos_Sonhos.jpg","description":"Um mesversário aconchegante com ursinhos, tons terrosos e luzes delicadas.","kind":"ai","sample":true,"customization":"O número de meses na imagem é apenas um exemplo e será adaptado ao mês solicitado. Informe o mês desejado no atendimento."},{"id":"mes-02","title":"Pequena Princesa","album":"Mesversários","image":"/images/mesversarios/MES_02_Pequena_Princesa.jpg","description":"Um cenário delicado com coroa, flores cor-de-rosa e castelo de conto de fadas.","kind":"ai","sample":true,"customization":"O número de meses na imagem é apenas um exemplo e será adaptado ao mês solicitado. Informe o mês desejado no atendimento."},{"id":"mes-03","title":"Safari Encantado","album":"Mesversários","image":"/images/mesversarios/MES_03_Safari_Encantado.jpg","description":"Uma aventura cheia de ternura com animais de pelúcia e tons naturais.","kind":"ai","sample":true,"customization":"O número de meses na imagem é apenas um exemplo e será adaptado ao mês solicitado. Informe o mês desejado no atendimento."},{"id":"mes-04","title":"Abelhinha do Amor","album":"Mesversários","image":"/images/mesversarios/MES_04_Abelhinha_do_Amor.jpg","description":"Um mesversário alegre com girassóis, abelhinhas e detalhes dourados.","kind":"ai","sample":true,"customization":"O número de meses na imagem é apenas um exemplo e será adaptado ao mês solicitado. Informe o mês desejado no atendimento."},{"id":"ani-01","title":"Princesa do Castelo","album":"Aniversários","image":"/images/aniversarios/ANI_01_Princesa_do_Castelo.jpg","description":"Uma celebração de conto de fadas com vestido dourado, rosas e cenário de castelo.","kind":"ai","sample":true,"customization":""},{"id":"ani-02","title":"Pequeno Cowboy","album":"Aniversários","image":"/images/aniversarios/ANI_02_Pequeno_Cowboy.jpg","description":"Uma aventura de aniversário no velho oeste, com chapéu, feno e decoração rústica.","kind":"ai","sample":true,"customization":""},{"id":"ani-03","title":"Aventura Jurássica","album":"Aniversários","image":"/images/aniversarios/ANI_03_Aventura_Jurassica.jpg","description":"Um aniversário de explorador entre folhagens e dinossauros de fantasia.","kind":"ai","sample":true,"customization":""},{"id":"ani-04","title":"Encantos do Fundo do Mar","album":"Aniversários","image":"/images/aniversarios/ANI_04_Fundo_do_Mar.jpg","description":"Um ensaio de aniversário inspirado no oceano, com corais, pérolas e tons brilhantes.","kind":"ai","sample":true,"customization":""},{"id":"newborn-demo","title":"Primeiros sonhos","album":"Recém-nascidos","image":"/images/studio-moon.svg","description":"Inspiração em uma atmosfera suave e acolhedora para um ensaio virtual de recém-nascido. Ilustração temporária, sem bebê real.","kind":"placeholder","sample":false,"customization":""},{"id":"demo-1","title":"Um céu de possibilidades","album":"Ensaios infantis","image":"/images/studio-balloons.svg","description":"Balões em tons delicados inspiram um cenário lúdico para um ensaio infantil personalizado. Ilustração temporária, sem personagem real.","kind":"placeholder","sample":false,"customization":""},{"id":"demo-2","title":"Pequenas grandes celebrações","album":"Mesversários","image":"/images/studio-cake.svg","description":"Um cenário doce para celebrar os primeiros meses, com cores e detalhes a combinar. Ilustração temporária.","kind":"placeholder","sample":false,"customization":""},{"id":"birthday-demo","title":"Uma festa de imaginação","album":"Aniversários","image":"/images/studio-gift.svg","description":"Presentes e cores suaves como inspiração para um aniversário temático. O tema e a composição serão definidos na conversa.","kind":"placeholder","sample":false,"customization":""},{"id":"season-demo","title":"Datas para encantar","album":"Datas comemorativas","image":"/images/studio-flowers.svg","description":"Detalhes florais como referência para celebrar datas especiais. Ilustração temporária que será substituída por um arquivo exclusivo.","kind":"placeholder","sample":false,"customization":""},{"id":"family-demo","title":"Laços e novos começos","album":"Gestantes e família","image":"/images/studio-balloons.svg","description":"Paleta delicada para inspirar composições de gestantes e família. Ilustração temporária, sem pessoas ou fotografias particulares.","kind":"placeholder","sample":false,"customization":""},{"id":"demo-3","title":"Um convite ao encanto","album":"Convites personalizados","image":"/images/studio-invitation.svg","description":"Um convite digital com atmosfera elegante para apresentar uma celebração. Textos e detalhes serão personalizados.","kind":"placeholder","sample":false,"customization":""},{"id":"transform-demo","title":"Entre sonhos e estrelas","album":"Transformações com IA","image":"/images/studio-moon.svg","description":"Uma atmosfera de lua e estrelas como referência para uma transformação digital com IA. Ilustração temporária, não uma fotografia final.","kind":"placeholder","sample":false,"customization":""},{"id":"1","title":"Horizontes tranquilos","album":"Transformações com IA","image":"/images/landscape.svg","description":"Acervo preservado: Horizontes tranquilos. Ilustração temporária para inspirar cores, cenários e transformações digitais; não representa uma fotografia de cliente.","kind":"placeholder","sample":false,"customization":""},{"id":"2","title":"Entre formas e cores","album":"Transformações com IA","image":"/images/shapes.svg","description":"Acervo preservado: Entre formas e cores. Ilustração temporária para inspirar cores, cenários e transformações digitais; não representa uma fotografia de cliente.","kind":"placeholder","sample":false,"customization":""},{"id":"3","title":"Geometria urbana","album":"Transformações com IA","image":"/images/architecture.svg","description":"Acervo preservado: Geometria urbana. Ilustração temporária para inspirar cores, cenários e transformações digitais; não representa uma fotografia de cliente.","kind":"placeholder","sample":false,"customization":""},{"id":"4","title":"Pausa para o essencial","album":"Transformações com IA","image":"/images/still-life.svg","description":"Acervo preservado: Pausa para o essencial. Ilustração temporária para inspirar cores, cenários e transformações digitais; não representa uma fotografia de cliente.","kind":"placeholder","sample":false,"customization":""},{"id":"5","title":"O silêncio das montanhas","album":"Transformações com IA","image":"/images/mountains.svg","description":"Acervo preservado: O silêncio das montanhas. Ilustração temporária para inspirar cores, cenários e transformações digitais; não representa uma fotografia de cliente.","kind":"placeholder","sample":false,"customization":""},{"id":"6","title":"Novas perspectivas","album":"Transformações com IA","image":"/images/orbit.svg","description":"Acervo preservado: Novas perspectivas. Ilustração temporária para inspirar cores, cenários e transformações digitais; não representa uma fotografia de cliente.","kind":"placeholder","sample":false,"customization":""}],"services":[{"id":"infantis","title":"Ensaios infantis","description":"Cenários lúdicos e delicados para valorizar a infância em composições digitais personalizadas.","image":"/images/studio-balloons.svg"},{"id":"mesversarios","title":"Mesversários","description":"Celebre cada nova descoberta com temas e cenários criados para registrar os primeiros meses.","image":"/images/studio-cake.svg"},{"id":"aniversarios","title":"Aniversários temáticos","description":"Cores, elementos e cenários inspirados no tema escolhido para tornar a data ainda mais especial.","image":"/images/studio-gift.svg"},{"id":"datas","title":"Datas comemorativas","description":"Criações para celebrar o Natal, a Páscoa e outras datas com carinho e originalidade.","image":"/images/studio-flowers.svg"},{"id":"convites","title":"Convites digitais","description":"Convites personalizados para compartilhar os detalhes da sua celebração em formato digital.","image":"/images/studio-invitation.svg"},{"id":"transformacoes","title":"Transformações fotográficas com IA","description":"Novas atmosferas, fundos e composições a partir de uma fotografia autorizada. O resultado é uma criação digital, não um registro documental.","image":"/images/studio-moon.svg"}],"packages":[{"id":"uma-foto","title":"Um toque de encanto","count":1,"cents":250},{"id":"cinco-fotos","title":"Pequena coleção","count":5,"cents":1000},{"id":"dez-fotos","title":"Memórias para guardar","count":10,"cents":2000}]}'::jsonb,1)
